import { bootstrapApplication } from '@angular/platform-browser';
import { StorefrontComponent } from './app';
bootstrapApplication(StorefrontComponent).catch((error) => console.error(error));

import { Component, computed, signal } from '@angular/core';

@Component({
  selector: 'galaxy-root',
  standalone: true,
  template: `<main>TODO Angular storefront</main>`
})
export class StorefrontComponent {
  readonly priceCents = signal(4950);
  readonly quantity = signal(1);
  readonly totalCents = computed(() => { throw new Error('TODO total'); });

  setQuantity(value: number): void {
    throw new Error('TODO quantity');
  }
}

import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { readFile, readdir, rm, stat } from 'node:fs/promises';
import test from 'node:test';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';

const run = promisify(execFile);
const root = fileURLToPath(new URL('..', import.meta.url));
const output = new URL('../dist-angular/', import.meta.url);

test('Angular CLI builds the standalone storefront application', { timeout: 240000 }, async () => {
  try {
    await run(process.execPath, ['node_modules/@angular/cli/bin/ng.js', 'build', '--configuration', 'development'], { cwd: root, env: { ...process.env, NG_CLI_ANALYTICS: 'false' }, maxBuffer: 4 * 1024 * 1024, timeout: 220000 });
    assert.equal((await stat(new URL('browser/index.html', output))).isFile(), true);
    const assets = await readdir(new URL('browser/', output));
    const bundles = assets.filter((name) => name.endsWith('.js'));
    const code = (await Promise.all(bundles.map((name) => readFile(new URL(`browser/${name}`, output), 'utf8')))).join('');
    assert.match(code, /Galaxy Angular Storefront/);
    assert.doesNotMatch(code, /TODO Angular storefront|TODO total|TODO quantity/);
  } finally {
    await rm(output, { recursive: true, force: true });
    await rm(new URL('../.angular/', import.meta.url), { recursive: true, force: true });
  }
});
